const b=$input.first().json.body;
if (!b || typeof b !== 'object' || Array.isArray(b) || Object.keys(b).sort().join(',') !== 'input,protocol,request_id' || b.protocol !== 'aes-n8n-v1' || typeof b.request_id !== 'string' || !/^[a-f0-9]{32}$/.test(b.request_id)) throw new Error('Invalid AES envelope');
const d=b.input;
if (!d || typeof d !== 'object' || Array.isArray(d) || Object.keys(d).join(',') !== 'rows' || !Array.isArray(d.rows) || d.rows.length<2 || d.rows.length>3) throw new Error('Invalid market input');
for (const r of d.rows) {
 if (!r || typeof r!=='object' || Array.isArray(r) || Object.keys(r).sort().join(',')!=='country,internet_bp,population' || typeof r.country!=='string' || !/^[A-Z]{3}$/.test(r.country) || !Number.isSafeInteger(r.population) || r.population<0 || r.population>2000000000 || !Number.isSafeInteger(r.internet_bp) || r.internet_bp<0 || r.internet_bp>10000) throw new Error('Invalid market row');
}
if (new Set(d.rows.map(r=>r.country)).size!==d.rows.length) throw new Error('Duplicate country');
const markets=d.rows.map(r=>({country:r.country,estimated_users:Math.floor(r.population*r.internet_bp/10000)})).sort((a,b)=>b.estimated_users-a.estimated_users || (a.country<b.country?-1:a.country>b.country?1:0));
return [{json:{protocol:'aes-n8n-v1',request_id:b.request_id,execution_id:String($execution.id),result:{markets}}}];
